package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Bitmap;import android.view.*;import android.widget.*;import app.layan.quran.*;import java.io.*;
/** Final APK: reuse an authenticated download with networking disabled, reopen and exercise original pager. */
public final class QiraatOfflineReopen extends Instrumentation {
 private int checks;public void onCreate(Bundle b){super.onCreate(b);start();}private void check(boolean v,String m){checks++;if(!v)throw new AssertionError(m);}private void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
 private void await(QiraatReaderActivity a)throws Exception{boolean[] ready={false};for(int i=0;i<240;i++){ui(()->ready[0]=a.currentPageReady());if(ready[0])return;SystemClock.sleep(250);}throw new AssertionError("Page not rendered");}
 private void screen(Activity a,String n)throws Exception{Bitmap b=NativeScreens.capture(this,a);check(b!=null,"Screenshot "+n);File dir=a.getExternalFilesDir("tests");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,n+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 public void onStart(){Bundle result=new Bundle();try{boolean[] reused={false};QiraatData.download(getTargetContext(),"hafs",(p,preparing)->{if(p==100&&preparing)reused[0]=true;});check(reused[0],"Saved download reused offline");check(QiraatData.downloaded(getTargetContext(),"idris"),"Other downloaded riwayah retained");QiraatReaderActivity a=(QiraatReaderActivity)startActivitySync(new Intent(getTargetContext(),QiraatReaderActivity.class).putExtra("riwayah","hafs").putExtra("page",1).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(a);check(a.currentPage()==1,"Offline opening");screen(a,"qiraat-final-1");ui(()->a.goToPage(300));await(a);check(a.currentPage()==300,"Page jump");screen(a,"qiraat-final-300");ui(()->a.goToPage(604));await(a);check(a.currentPage()==604,"Last page");screen(a,"qiraat-final-604");ui(()->a.goToPage(300));await(a);ui(a::finish);QiraatReaderActivity b=(QiraatReaderActivity)startActivitySync(new Intent(getTargetContext(),QiraatReaderActivity.class).putExtra("riwayah","hafs").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(b);check(b.currentPage()==300,"Saved position on reopening");ui(b::finish);
  org.json.JSONArray all=QiraatData.catalog(getTargetContext()).getJSONArray("riwayat");for(int i=0;i<all.length();i++){String id=all.getJSONObject(i).getString("id");try(QiraatData.Book book=new QiraatData.Book(getTargetContext(),id)){check(book.pageCount()==604,"Complete final PDF "+id);for(int p:new int[]{1,300,604}){Bitmap bitmap=book.render(p,400);int ink=0;boolean edges=true;for(int y=0;y<bitmap.getHeight();y+=2){for(int x=0;x<bitmap.getWidth();x+=2)if((bitmap.getPixel(x,y)>>>24)>0)ink++;for(int x=0;x<8;x++)if((bitmap.getPixel(x,y)>>>24)>0||(bitmap.getPixel(399-x,y)>>>24)>0)edges=false;}check(ink>100,"Printed glyphs "+id+" "+p);check(edges,"Safe page gutters "+id+" "+p);bitmap.recycle();}}}
  android.preference.PreferenceManager.getDefaultSharedPreferences(getTargetContext()).edit().putBoolean("nightMode",true).commit();QiraatReaderActivity night=(QiraatReaderActivity)startActivitySync(new Intent(getTargetContext(),QiraatReaderActivity.class).putExtra("riwayah","warsh").putExtra("page",3).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(night);screen(night,"qiraat-final-warsh-night");ui(night::finish);android.preference.PreferenceManager.getDefaultSharedPreferences(getTargetContext()).edit().putBoolean("nightMode",false).commit();
  Activity section=startActivitySync(new Intent(getTargetContext(),QiraatActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ListView list=section.findViewById(QiraatActivity.READINGS_LIST);ui(()->list.performItemClick(list.getAdapter().getView(9,null,list),9,9));check(list.getCount()==2,"Riwayah list");screen(section,"qiraat-final-downloads");ui(section::finish);check(getTargetContext().getPackageManager().getPackageInfo("app.layan.quran",0).versionName.equals("18.12"),"Requested version");result.putString("result","PASS "+checks+" assertions: final APK cached-download path, all twenty native PDFs, safe gutters, offline pages and permanent resume");finish(Activity.RESULT_OK,result);}catch(Throwable t){result.putString("error",android.util.Log.getStackTraceString(t));finish(Activity.RESULT_CANCELED,result);}}
}
